module voting_system #(\n    parameter N = 8,\n    parameter DATA_WIDTH = 2\n)(\n    input clk,\n    input rst_n,\n    input start,\n    input [DATA_WIDTH-1:0] arr_0,\n    input [DATA_WIDTH-1:0] arr_1,\n    input [DATA_WIDTH-1:0] arr_2,\n    input [DATA_WIDTH-1:0] arr_3,\n    input [DATA_WIDTH-1:0] arr_4,\n    input [DATA_WIDTH-1:0] arr_5,\n    input [DATA_WIDTH-1:0] arr_6,\n    input [DATA_WIDTH-1:0] arr_7,\n    output reg done,\n    output reg impossible,\n    output reg [7:0] min_swaps\n);\n\n    // State declarations\n    localparam [3:0] IDLE      = 4'd0;\n    localparam [3:0] INIT      = 4'd1;\n    localparam [3:0] LOAD_S    = 4'd2;\n    localparam [3:0] COUNT_S   = 4'd3;\n    localparam [3:0] CHECK_T   = 4'd4;\n    localparam [3:0] BUILD_C   = 4'd5;\n    localparam [3:0] SIMUL     = 4'd6;\n    localparam [3:0] SCORE_C   = 4'd7;\n    localparam [3:0] CALC_COST = 4'd8;\n    localparam [3:0] UPDATE    = 4'd9;\n    localparam [3:0] FINISHED  = 4'd10;\n\n    reg [3:0] state, next_state;\n    reg [7:0] subset;\n    reg [3:0] cnt, i;\n    reg [3:0] original_teller_count;\n    reg [3:0] target_count;\n    reg [3:0] voter_idx;\n    reg [3:0] teller_pos [0:7];\n    reg [3:0] target_pos [0:7];\n    reg [1:0] input_val [0:7];\n    reg [1:0] modified_val [0:7];\n    reg [1:0] vote_type;\n    reg valid_subset;\n    reg [3:0] points1, points2;\n    reg [7:0] current_cost;\n    reg [7:0] best_cost;\n    reg found_valid;\n    reg [7:0] bit_counter;\n    reg [7:0] loop_index;\n    reg [3:0] sim_index;\n\n    // Initialize all arrays in reset\n    always @(posedge clk or negedge rst_n) begin\n        if (!rst_n) begin\n            state <= IDLE;\n            done <= 1'b0;\n            impossible <= 1'b0;\n            min_swaps <= 8'd0;\n            loop_index <= 8'd0;\n            subset <= 8'd0;\n            current_cost <= 8'd0;\n            best_cost <= 8'hFF;\n            found_valid <= 1'b0;\n            for (i = 0; i < 8; i = i + 1) begin\n                teller_pos[i] <= 4'd0;\n                target_pos[i] <= 4'd0;\n                input_val[i] <= 2'd0;\n                modified_val[i] <= 2'd0;\n            end\n        end else begin\n            case (state)\n                IDLE: begin\n                    done <= 1'b0;\n                    impossible <= 1'b0;\n                    if (start) begin\n                        state <= INIT;\n                        input_val[0] <= arr_0;\n                        input_val[1] <= arr_1;\n                        input_val[2] <= arr_2;\n                        input_val[3] <= arr_3;\n                        input_val[4] <= arr_4;\n                        input_val[5] <= arr_5;\n                        input_val[6] <= arr_6;\n                        input_val[7] <= arr_7;\n                        subset <= 8'd0;\n                        loop_index <= 8'd0;\n                    end\n                end\n\n                INIT: begin\n                    original_teller_count <= 4'd0;\n                    cnt <= 4'd0;\n                    state <= LOAD_S;\n                end\n\n                LOAD_S: begin\n                    // Count original tellers and store positions\n                    if (cnt < N) begin\n                        if (input_val[cnt] == 2'd0) begin\n                            teller_pos[original_teller_count] <= cnt;\n                            original_teller_count <= original_teller_count + 4'd1;\n                        end\n                        cnt <= cnt + 4'd1;\n                    end\n                    else begin\n                        cnt <= 4'd0;\n                        subset <= 8'd0;\n                        loop_index <= 8'd0;\n                        state <= COUNT_S;\n                    end\n                end\n\n                COUNT_S: begin\n                    // Iterate through all subsets (0-255)\n                    if (loop_index < 8'd255) begin\n                        loop_index <= loop_index + 8'd1;\n                        subset <= loop_index;\n                        bit_counter <= 8'd0;\n                        cnt <= 4'd0;\n                        state <= CHECK_T;\n                    end\n                    else state <= FINISHED;\n                end\n\n                CHECK_T: begin\n                    // Count set bits in subset\n                    if (cnt < 4'd7) begin\n                        bit_counter <= bit_counter + subset[cnt];\n                        cnt <= cnt + 4'd1;\n                    end\n                    else begin\n                        target_count <= bit_counter + subset[7];\n                        state <= BUILD_C;\n                        voter_idx <= 4'd0;\n                        sim_index <= 4'd0;\n                        cnt <= 4'd0;\n                    end\n                end\n\n                BUILD_C: begin\n                    // Build modified configuration\n                    valid_subset <= (target_count == original_teller_count);\n                    if (cnt < N) begin\n                        if (subset[cnt])\n                            modified_val[cnt] <= 2'd0;\n                        else begin\n                            // Assign next non-teller value\n                            while ((sim_index < N) && (input_val[sim_index] == 2'd0))\n                                sim_index <= sim_index + 4'd1;\n                            if (sim_index < N) begin\n                                modified_val[cnt] <= input_val[sim_index];\n                                sim_index <= sim_index + 4'd1;\n                            end\n                        end\n                        cnt <= cnt + 4'd1;\n                    end\n                    else begin\n                        points1 <= 4'd0;\n                        points2 <= 4'd0;\n                        cnt <= 4'd0;\n                        state <= SIMUL;\n                    end\n                end\n\n                SIMUL: begin\n                    // Simulate election\n                    if (cnt < N) begin\n                        vote_type <= modified_val[cnt];\n                        if (vote_type == 2'd1) points1 <= points1 + 4'd1;\n                        else if (vote_type == 2'd2) points2 <= points2 + 4'd1;\n                        cnt <= cnt + 4'd1;\n                    end\n                    else begin\n                        state <= SCORE_C;\n                    end\n                end\n\n                SCORE_C: begin\n                    // Check score validity\n                    valid_subset <= valid_subset && (points1 > points2);\n                    if (valid_subset) state <= CALC_COST;\n                    else state <= COUNT_S;\n                end\n\n                CALC_COST: begin\n                    // Compute swap cost\n                    current_cost <= 8'd0;\n                    cnt <= 4'd0;\n                    for (i = 0; i < original_teller_count; i = i + 1) begin\n                        if (!subset[teller_pos[i]])\n                            current_cost <= current_cost + 8'd1;\n                    end\n                    for (i = 0; i < N; i = i + 1) begin\n                        if (subset[i] && (input_val[i] != 2'd0))\n                            current_cost <= current_cost + 8'd1;\n                    end\n                    state <= UPDATE;\n                end\n\n                UPDATE: begin\n                    // Update best cost\n                    if (current_cost < best_cost) begin\n                        best_cost <= current_cost;\n                        found_valid <= 1'b1;\n                    end\n                    state <= COUNT_S;\n                end\n\n                FINISHED: begin\n                    done <= 1'b1;\n                    impossible <= !found_valid;\n                    min_swaps <= found_valid ? best_cost : 8'd0;\n                    state <= IDLE;\n                end\n\n                default: state <= IDLE;\n            endcase\n        end\n    end\nendmodule